function qmTestAllSpecials(){qmTestDreamiesSpecial();setTimeout(qmTestWyrmfireSpecial,1250);setTimeout(qmTestTeaBiscuitsSpecial,2750);setTimeout(qmTestVerdantGroveSpecial,3950)}
