// ============================================================
// NATURAL QUIDDITCH SET-PIECE SCHEDULE
// Numeric live match ids are sequential, so use disjoint cycles rather than
// independent hashes. This guarantees exactly one penalty in every 8 matches
// and one Golden Snitch in every 14 matches, with no overlap and no long dry
// streaks. Non-numeric legacy ids retain the deterministic hash fallback.
// ============================================================
function qmNaturalQuidditchSetPiece(matchId){
  const raw=String(matchId??'').trim();
  const numeric=Number(raw);
  if(raw&&Number.isSafeInteger(numeric)&&numeric>=0){
    if(numeric%8===0)return 'penalty';
    // 7 is odd, so this slot can never collide with a multiple of 8.
    if(numeric%14===7)return 'snitch';
    return '';
  }
  if(qmHashNumber(`${raw}:has-penalty`)%8===0)return 'penalty';
  return qmHashNumber(`${raw}:has-snitch`)%14===0?'snitch':'';
}
window.qmNaturalQuidditchSetPiece=qmNaturalQuidditchSetPiece;

// ============================================================
// QUIDDITCH PENALTIES — rare, synchronised broadcast event.
// Exactly one in every eight numeric live matches receives one penalty.
// The event is deterministic from the shared match id so every
// viewer sees the same taker, timing and outcome. Admin testing
// is visual-only and never changes the shared scoreline.
// ============================================================
(function installQuidditchPenaltyEvent(){
  if(window.__repoQuidditchPenaltyInstalled)return;
  window.__repoQuidditchPenaltyInstalled=true;

  const penalty={
    active:false,
    test:false,
    matchId:null,
    autoTriggered:false,
    timers:new Set(),
    overlay:null,
    ball:null,
    caption:null
  };
  window.repoQuidditchPenaltyState=penalty;

  const later=(fn,ms)=>{
    const timer=setTimeout(()=>{penalty.timers.delete(timer);fn();},ms);
    penalty.timers.add(timer);
    return timer;
  };
  const clearTimers=()=>{for(const timer of penalty.timers)clearTimeout(timer);penalty.timers.clear();};

  const style=document.createElement('style');
  style.id='repoQuidditchPenaltyStyles';
  style.textContent=`
    #quidditchModePitch .qm-penalty-alert{
      position:absolute;left:50%;top:47%;z-index:145;width:min(390px,48%);
      transform:translate(-50%,-50%);pointer-events:none;filter:drop-shadow(0 8px 10px rgba(0,0,0,.78));
      animation:qmPenaltyPop .22s ease-out both,qmPenaltyShake .13s linear .22s 7;
    }
    #quidditchModePitch .qm-penalty-alert img{display:block;width:100%;height:auto;image-rendering:pixelated}
    #quidditchModePitch .qm-penalty-caption{
      position:absolute;left:50%;top:69%;z-index:146;transform:translate(-50%,-50%);
      min-width:235px;max-width:76%;padding:8px 18px;border:2px solid #f3c44e;
      background:linear-gradient(#6b1c17,#3e0d0b);box-shadow:0 3px 0 #1c0706,0 0 16px rgba(255,194,54,.35);
      color:#ffe58c;font:900 15px/1.15 Georgia,serif;text-align:center;text-transform:uppercase;
      letter-spacing:.8px;pointer-events:none;animation:qmPenaltyCaption .18s ease-out both;
    }
    #quidditchModePitch .qm-penalty-caption.is-result{top:72%;font-size:17px}
    #quidditchModePitch .qm-penalty-spot{
      position:absolute;left:50%;top:51%;z-index:20;width:34px;height:34px;transform:translate(-50%,-50%);
      border:3px solid rgba(255,213,74,.92);border-radius:50%;box-shadow:0 0 0 4px rgba(90,15,12,.72),0 0 18px #ffc83d;
      pointer-events:none;animation:qmPenaltySpot .72s ease-in-out infinite alternate;
    }
    #quidditchModePitch.is-penalty-event .qm-pet{z-index:55!important}
    #quidditchModePitch.is-penalty-event .qm-pet.is-penalty-taker{z-index:70!important;filter:drop-shadow(0 0 8px #ffd63c)}
    #quidditchModePitch.is-penalty-event .qm-pet.is-penalty-keeper{z-index:68!important;filter:drop-shadow(0 0 7px rgba(255,255,255,.8))}
    @keyframes qmPenaltyPop{from{opacity:0;transform:translate(-50%,-50%) scale(.72)}to{opacity:1;transform:translate(-50%,-50%) scale(1)}}
    @keyframes qmPenaltyShake{0%,100%{transform:translate(-50%,-50%) rotate(0)}25%{transform:translate(calc(-50% - 5px),calc(-50% + 1px)) rotate(-1.5deg)}75%{transform:translate(calc(-50% + 5px),calc(-50% - 1px)) rotate(1.5deg)}}
    @keyframes qmPenaltyCaption{from{opacity:0;transform:translate(-50%,-42%) scale(.9)}to{opacity:1;transform:translate(-50%,-50%) scale(1)}}
    @keyframes qmPenaltySpot{from{opacity:.45;transform:translate(-50%,-50%) scale(.82)}to{opacity:1;transform:translate(-50%,-50%) scale(1.08)}}
    @media(max-width:760px){
      #quidditchModePitch .qm-penalty-alert{width:min(300px,58%)}
      #quidditchModePitch .qm-penalty-caption{font-size:12px;min-width:185px;padding:6px 11px}
    }
  `;
  document.head.appendChild(style);

  const playPenaltyWhistle=()=>{
    try{
      const whistle=new Audio('assets/quidditch-kickoff-whistle.mp3');
      whistle.preload='auto';whistle.volume=.92;whistle.currentTime=0;
      whistle.play().catch(()=>{});
      later(()=>{try{whistle.pause();whistle.src='';}catch(_){}},4200);
    }catch(_){}
  };

  const getPitch=()=>document.getElementById('quidditchModePitch');
  const removePenaltyNodes=()=>{
    penalty.overlay?.remove();penalty.overlay=null;
    penalty.caption?.remove();penalty.caption=null;
    penalty.ball?.remove();penalty.ball=null;
    const pitch=getPitch();
    pitch?.classList.remove('is-penalty-event');
    pitch?.querySelectorAll('.qm-penalty-alert,.qm-penalty-caption,.qm-penalty-spot').forEach(node=>node.remove());
    qmState?.pets?.forEach(p=>p.classList.remove('is-penalty-taker','is-penalty-keeper'));
  };

  const restoreBroadcast=()=>{
    window.qmCancelBarrySetPiece?.();
    removePenaltyNodes();
    penalty.active=false;penalty.test=false;
    if(!qmState?.open||qmState.liveState?.phase!=='live')return;
    qmState.busy=false;
    try{qmStartSyncedBroadcast(qmState.liveState);}catch(error){console.warn('Penalty broadcast resume:',error);}
  };

  const stopCurrentBroadcast=()=>{
    if(typeof qmSync!=='undefined'&&qmSync.raf){cancelAnimationFrame(qmSync.raf);qmSync.raf=null;}
    clearInterval(qmState.tick);qmState.tick=null;qmState.busy=true;qmState.carrier=null;
    const pitch=getPitch();
    pitch?.querySelectorAll('.qm-quaffle').forEach(node=>node.remove());
    qmState.pets.forEach(p=>p.classList.remove('has-ball'));
  };

  const setCaption=(text,result=false)=>{
    const pitch=getPitch();if(!pitch)return;
    penalty.caption?.remove();
    const caption=document.createElement('div');caption.className=`qm-penalty-caption${result?' is-result':''}`;caption.textContent=text;
    pitch.appendChild(caption);penalty.caption=caption;
  };

  const showPenaltyAlert=()=>{
    const pitch=getPitch();if(!pitch)return;
    const alert=document.createElement('div');alert.className='qm-penalty-alert';
    alert.innerHTML='<img src="assets/quidditch-penalty-popup.png" alt="Penalty">';
    pitch.appendChild(alert);penalty.overlay=alert;
  };

  const rosterForSide=(state,side)=>{
    const rows=(Array.isArray(state?.roster)?state.roster:[]).filter(row=>row.side===side);
    return rows;
  };
  const petForRow=(row,side)=>{
    const name=String(row?.pet_name||row?.petName||row?.username||'Pet').trim();
    return qmState.pets.find(p=>p.dataset.team===side&&p.dataset.name===name)||qmState.pets.find(p=>p.dataset.team===side)||null;
  };

  const gatherPlayers=(taker,keeper)=>{
    const pets=qmState.pets.filter(p=>p?.isConnected);
    const others=pets.filter(p=>p!==taker&&p!==keeper);
    const ring=[[-13,-13],[13,-13],[-16,11],[16,11],[-3,18],[3,-19],[20,0],[-20,0]];
    pets.forEach(p=>{p.style.transition='left 1.15s ease, top 1.15s ease, transform .25s ease';});
    others.forEach((p,index)=>{
      const [dx,dy]=ring[index%ring.length];qmMovePet(p,50+dx,51+dy,1.12);
    });
    if(taker){taker.classList.add('is-penalty-taker');qmMovePet(taker,50,51,1.05);}
    if(keeper){keeper.classList.add('is-penalty-keeper');qmMovePet(keeper,50+(keeper.dataset.team==='left'?-7:7),37,1.05);}
  };

  const commitPenaltyGoal=async(state,taker,side)=>{
    if(!state?.match_id||!taker)return null;
    const eventKey=`penalty:${state.match_id}`;
    try{
      const {data,error}=await db.rpc('record_live_quidditch_goal',{
        p_match_id:state.match_id,
        p_side:side,
        p_pet_name:String(taker.dataset.name||'Pet').slice(0,80),
        p_event_key:eventKey
      });
      if(error){console.warn('Quidditch penalty score sync:',error);return null;}
      const row=data?.[0]||null;if(row)qmApplyCanonicalScore(row);return row;
    }catch(error){console.warn('Quidditch penalty score sync:',error);return null;}
  };

  async function runPenaltyEvent({test=false,state=qmState.liveState}={}){
    if(penalty.active||!qmState?.open||state?.phase!=='live'||!qmState.pets?.length)return false;
    penalty.active=true;penalty.test=!!test;clearTimers();removePenaltyNodes();stopCurrentBroadcast();
    const pitch=getPitch();if(!pitch){penalty.active=false;return false;}
    pitch.classList.add('is-penalty-event');playPenaltyWhistle();showPenaltyAlert();window.qmStartBarrySetPiece?.('penalty');

    const matchId=String(state.match_id||'admin-test');
    let awardedSide=(qmHashNumber(`${matchId}:penalty-side`)%2===0)?'left':'right';
    if(!rosterForSide(state,awardedSide).length)awardedSide=awardedSide==='left'?'right':'left';
    const rows=rosterForSide(state,awardedSide);
    const row=rows[qmHashNumber(`${matchId}:penalty-taker`)%Math.max(1,rows.length)]||null;
    const taker=petForRow(row,awardedSide)||qmState.pets.find(p=>p.dataset.team===awardedSide)||qmState.pets[0];
    const defendingSide=awardedSide==='left'?'right':'left';
    const defenders=qmState.pets.filter(p=>p.dataset.team===defendingSide);
    const keeper=defenders[qmHashNumber(`${matchId}:penalty-keeper`)%Math.max(1,defenders.length)]||null;
    const takerName=taker?.dataset.name||'Pet';
    const teamName=awardedSide==='left'?qmState.leftName:qmState.rightName;
    const targetX=awardedSide==='left'?82.4:17.6,targetY=49.2;
    const scores=test?true:qmUnit(`${matchId}:penalty-score`)<.57;

    setCaption(`FOUL ON ${takerName} — PENALTY TO ${teamName}`);
    qmAddCommentary?.('penaltyAwarded',{pet:takerName,team:teamName},true);
    later(()=>gatherPlayers(taker,keeper),580);
    later(()=>{
      penalty.overlay?.remove();penalty.overlay=null;
      const spot=document.createElement('i');spot.className='qm-penalty-spot';pitch.appendChild(spot);
      if(keeper)qmMovePet(keeper,awardedSide==='left'?79.2:20.8,targetY,1.0);
      if(taker)qmMovePet(taker,50,51,.85);
      setCaption(`${takerName} STEPS UP…`);
    },1850);
    later(()=>{
      if(!penalty.active)return;
      const ball=document.createElement('i');ball.className='qm-quaffle';ball.style.left='50%';ball.style.top='51%';ball.style.zIndex='82';pitch.appendChild(ball);penalty.ball=ball;
      setCaption('PENALTY SHOT!');qmPlayRandomSound?.(qmShotSoundPaths);
      requestAnimationFrame(()=>requestAnimationFrame(()=>{
        ball.style.transition='left .62s ease-in, top .62s ease-in, transform .62s linear';
        ball.style.left=`${targetX}%`;ball.style.top=`${targetY}%`;ball.style.transform='translate(-50%,-50%) rotate(900deg) scale(.72)';
      }));
    },3150);
    later(async()=>{
      if(!penalty.active)return;
      if(scores){
        penalty.ball?.remove();penalty.ball=null;
        qmFireworks(targetX,targetY);qmPlayGoalSound();
        taker?.classList.add('is-celebrating');later(()=>taker?.classList.remove('is-celebrating'),1200);
        setCaption(test?'PENALTY SCORED — TEST ONLY':'PENALTY SCORED!',true);
        if(!test){
          window.__qmPenaltyGoals=window.__qmPenaltyGoals||{};
          const matchPenalties=window.__qmPenaltyGoals[String(state.match_id||'') ]||(window.__qmPenaltyGoals[String(state.match_id||'')]={});
          matchPenalties[takerName]=(Number(matchPenalties[takerName])||0)+1;
        }
        qmAddCommentary?.('penaltyScored',{pet:takerName,team:teamName},true);
        window.qmResolveBarrySetPiece?.(true,`${takerName} scores the penalty!`);
        if(!test)await commitPenaltyGoal(state,taker,awardedSide);
      }else{
        if(penalty.ball){
          penalty.ball.style.transition='left .22s ease-out, top .22s ease-out, transform .22s linear';
          penalty.ball.style.left=`${targetX+(awardedSide==='left'?-6:6)}%`;
          penalty.ball.style.top=`${targetY-8}%`;
          penalty.ball.style.transform='translate(-50%,-50%) rotate(1120deg) scale(.82)';
        }
        qmPlayRandomSound?.(qmReboundSoundPaths);setCaption('PENALTY MISSED!',true);
        qmAddCommentary?.('penaltyMissed',{pet:takerName,team:teamName},true);
        window.qmResolveBarrySetPiece?.(false,`${takerName} misses the penalty.`);
      }
    },3850);
    later(restoreBroadcast,5600);
    return true;
  }
  window.qmTestPenaltyEvent=()=>runPenaltyEvent({test:true,state:qmState.liveState});

  // Keep the deterministic broadcast paused while the set-piece animation plays.
  if(typeof qmStartSyncedBroadcast==='function'){
    const baseStartSyncedBroadcast=qmStartSyncedBroadcast;
    qmStartSyncedBroadcast=function(state){if(penalty.active)return;return baseStartSyncedBroadcast(state);};
  }
  if(typeof qmShowSharedGoal==='function'){
    const baseShowSharedGoal=qmShowSharedGoal;
    qmShowSharedGoal=function(state){if(penalty.active)return;return baseShowSharedGoal(state);};
  }
  if(typeof qmApplyLiveState==='function'){
    const baseApplyLiveState=qmApplyLiveState;
    qmApplyLiveState=function(state){
      const result=baseApplyLiveState(state);
      if(!state||!qmState.open)return result;
      const matchId=String(state.match_id||'');
      if(matchId!==penalty.matchId){
        penalty.matchId=matchId;penalty.autoTriggered=false;
        if(penalty.active&&!penalty.test){clearTimers();restoreBroadcast();}
      }
      if(penalty.active){
        if(typeof qmSync!=='undefined'&&qmSync.raf){cancelAnimationFrame(qmSync.raf);qmSync.raf=null;}
        return result;
      }
      if(state.phase!=='live'||penalty.autoTriggered)return result;
      // Exact 1-in-8 deterministic schedule shared by every viewer.
      const eligible=qmNaturalQuidditchSetPiece(matchId)==='penalty';
      if(!eligible)return result;
      const elapsed=Math.max(0,180-Number(state.phase_seconds||180));
      const triggerAt=42+(qmHashNumber(`${matchId}:penalty-time`)%88); // 0:42–2:09
      // Trigger once the scheduled moment has passed. Do not use a narrow
      // polling window: a slow/paused tab or delayed live-state refresh could
      // otherwise skip the penalty for the entire match.
      if(elapsed>=triggerAt){
        penalty.autoTriggered=true;runPenaltyEvent({test:false,state});
      }
      return result;
    };
  }

  const ensureAdminButton=()=>{
    const panel=document.getElementById('qmAdminSpecialTester');
    if(!panel||document.getElementById('qmTestPenaltyEvent'))return;
    const button=document.createElement('button');button.type='button';button.id='qmTestPenaltyEvent';button.textContent='TEST PENALTY';
    button.title='Preview a Quidditch penalty without changing the score';
    button.addEventListener('click',()=>{
      const isCat=String(character?.username||'').toLowerCase()==='catasthma';
      if(!isCat||!toaState?.adminMode)return;
      if(!qmState.open||qmState.liveState?.phase!=='live'){toast('Open Quidditch Mode during a live match to test a penalty.',3600);return;}
      runPenaltyEvent({test:true,state:qmState.liveState});
    });
    const allButton=panel.querySelector('#qmTestAllSpecials');
    if(allButton?.parentElement)allButton.parentElement.appendChild(button);else panel.appendChild(button);
  };
  ensureAdminButton();setTimeout(ensureAdminButton,120);setTimeout(ensureAdminButton,600);
  const adminObserver=new MutationObserver(ensureAdminButton);adminObserver.observe(document.documentElement,{childList:true,subtree:true});

  const abortPenalty=()=>{clearTimers();window.qmCancelBarrySetPiece?.();removePenaltyNodes();penalty.active=false;penalty.test=false;qmState.busy=false;};
  window.qmAbortPenaltyEvent=abortPenalty;
  const baseClose=closeQuidditchMode;
  closeQuidditchMode=function(){abortPenalty();return baseClose();};
  document.getElementById('quidditchModeClose')?.addEventListener('click',abortPenalty,true);
  document.getElementById('quidditchModeOverlay')?.addEventListener('click',event=>{if(event.target===event.currentTarget)abortPenalty();},true);
  document.addEventListener('keydown',event=>{if(event.key==='Escape'&&penalty.active)abortPenalty();},true);
})();

// ============================================================
// QUIDDITCH GOLDEN SNITCH — rare, synchronised spectator event.
// Exactly one in every fourteen numeric live matches receives one Snitch chase.
// The shared match id deterministically controls the trigger time,
// flight path, collisions and catcher so all viewers see the same
// sequence. CatAsthma's TEST SNITCH preview is visual-only.
// ============================================================
(function installQuidditchGoldenSnitchEvent(){
  if(window.__repoQuidditchSnitchInstalled)return;
  window.__repoQuidditchSnitchInstalled=true;

  const snitch={
    active:false,
    test:false,
    matchId:'',
    autoTriggered:false,
    lockedFinal:false,
    winnerSide:'',
    winnerPet:'',
    caughtAt:0,
    finishedAt:0,
    finishCommitted:false,
    finishWatchdog:null,
    handoffRunning:false,
    handoffLastAt:0,
    finalState:null,
    latestState:null,
    timers:new Set(),
    alert:null,
    caption:null,
    sprite:null,
    winnerBanner:null,
    raf:null,
    chasePath:null,
    chaseStartedAt:0,
    chaseDuration:0
  };
  window.repoQuidditchSnitchState=snitch;

  const later=(fn,ms)=>{
    const timer=setTimeout(()=>{snitch.timers.delete(timer);fn();},ms);
    snitch.timers.add(timer);
    return timer;
  };
  const stopChaseAnimation=()=>{if(snitch.raf){cancelAnimationFrame(snitch.raf);snitch.raf=null;}};
  const clearFinishWatchdog=()=>{if(snitch.finishWatchdog){clearInterval(snitch.finishWatchdog);snitch.finishWatchdog=null;}};
  const clearTimers=()=>{stopChaseAnimation();for(const timer of snitch.timers)clearTimeout(timer);snitch.timers.clear();};
  const getPitch=()=>document.getElementById('quidditchModePitch');
  const getMatchId=state=>String(state?.match_id||'admin-snitch-test');
  const SNITCH_POST_SECONDS=30;
  const snitchPostSeconds=()=>Math.max(0,SNITCH_POST_SECONDS-Math.floor((Date.now()-Number(snitch.finishedAt||Date.now()))/1000));

  const style=document.createElement('style');
  style.id='repoQuidditchSnitchStyles';
  style.textContent=`
    #quidditchModePitch .qm-snitch-alert{
      position:absolute;left:50%;top:47%;z-index:150;width:min(430px,52%);
      transform:translate(-50%,-50%);pointer-events:none;
      filter:drop-shadow(0 10px 14px rgba(0,0,0,.82));
      animation:qmSnitchPop .22s ease-out both,qmSnitchShake .13s linear .22s 7;
    }
    #quidditchModePitch .qm-snitch-alert img{display:block;width:100%;height:auto;image-rendering:pixelated}
    #quidditchModePitch .qm-snitch-caption{
      position:absolute;left:50%;top:70%;z-index:151;transform:translate(-50%,-50%);
      min-width:265px;max-width:82%;padding:8px 18px;border:2px solid #f3c44e;
      background:linear-gradient(#6b1c17,#3e0d0b);box-shadow:0 3px 0 #1c0706,0 0 16px rgba(255,194,54,.35);
      color:#ffe58c;font:900 15px/1.15 Georgia,serif;text-align:center;text-transform:uppercase;
      letter-spacing:.8px;pointer-events:none;animation:qmSnitchCaption .18s ease-out both;
    }
    #quidditchModePitch .qm-snitch-caption.is-result{top:74%;font-size:17px}
    #quidditchModePitch.is-snitch-event .qm-pet{z-index:58!important}
    #quidditchModePitch.is-snitch-event .qm-pet.is-snitch-catcher{z-index:78!important;filter:drop-shadow(0 0 5px #fff) drop-shadow(0 0 14px #ffcf35);animation:qmSnitchCatchPulse .34s ease-in-out 3 alternate}
    #quidditchModePitch .qm-snitch-catcher-label{position:absolute;left:50%;bottom:calc(100% + 8px);transform:translateX(-50%);white-space:nowrap;padding:5px 9px;border:2px solid #ffd84d;border-radius:8px;background:linear-gradient(#67170f,#310906);box-shadow:0 3px 0 #160403,0 0 12px rgba(255,215,65,.48);color:#fff0a6;font:900 12px/1 Georgia,serif;letter-spacing:.55px;text-transform:uppercase;pointer-events:none;animation:qmSnitchCaughtLabel .18s ease-out both}
    @keyframes qmSnitchCatchPulse{from{transform:scale(1)}to{transform:scale(1.09)}}
    @keyframes qmSnitchCaughtLabel{from{opacity:0;transform:translate(-50%,6px) scale(.9)}to{opacity:1;transform:translate(-50%,0) scale(1)}}
    #quidditchModePitch .qm-golden-snitch{
      position:absolute;left:50%;top:50%;z-index:90;width:40px;height:24px;
      transform:translate(-50%,-50%);pointer-events:none;
      filter:drop-shadow(0 0 5px #fff3a0) drop-shadow(0 0 9px rgba(255,201,44,.9));
      animation:qmSnitchBob .34s ease-in-out infinite alternate;
    }
    #quidditchModePitch .qm-golden-snitch img{
      display:block;width:100%;height:100%;object-fit:contain;image-rendering:pixelated;
    }
    #quidditchModePitch .qm-pet.is-snitch-bumped>.pet-sprite,
    #quidditchModePitch .qm-pet.is-snitch-bumped>.qm-broom{
      animation:qmSnitchBump .42s ease-out both;
    }
    #quidditchModePitch .qm-snitch-winner{
      position:absolute;left:50%;top:16%;z-index:152;transform:translateX(-50%);
      min-width:290px;max-width:84%;padding:10px 16px 12px;border:2px solid #ffd24a;border-radius:12px;
      background:linear-gradient(#54120e,#240706);box-shadow:0 8px 18px rgba(0,0,0,.6),0 0 16px rgba(255,214,74,.28);
      text-align:center;pointer-events:none;animation:qmSnitchWinner .22s ease-out both;
    }
    #quidditchModePitch .qm-snitch-winner strong{display:block;color:#ffeaa0;font:900 14px/1.05 Georgia,serif;letter-spacing:.95px;text-transform:uppercase}
    #quidditchModePitch .qm-snitch-winner b{display:block;margin-top:4px;color:#fff3c8;font:900 22px/1 Georgia,serif;text-transform:uppercase}
    #quidditchModePitch .qm-snitch-winner small{display:block;margin-top:5px;color:#f2d992;font:700 11px/1.15 Georgia,serif;letter-spacing:.35px;text-transform:uppercase}
    @keyframes qmSnitchPop{from{opacity:0;transform:translate(-50%,-50%) scale(.72)}to{opacity:1;transform:translate(-50%,-50%) scale(1)}}
    @keyframes qmSnitchShake{0%,100%{transform:translate(-50%,-50%) rotate(0)}25%{transform:translate(calc(-50% - 5px),calc(-50% + 1px)) rotate(-1.5deg)}75%{transform:translate(calc(-50% + 5px),calc(-50% - 1px)) rotate(1.5deg)}}
    @keyframes qmSnitchCaption{from{opacity:0;transform:translate(-50%,-42%) scale(.9)}to{opacity:1;transform:translate(-50%,-50%) scale(1)}}
    @keyframes qmSnitchBob{from{transform:translate(-50%,-50%) rotate(-7deg) translateY(1px)}to{transform:translate(-50%,-50%) rotate(7deg) translateY(-2px)}}
    @keyframes qmSnitchBump{0%{transform:translateX(0) rotate(0)}42%{transform:translateX(var(--snitch-bump-x,7px)) rotate(var(--snitch-bump-r,12deg))}100%{transform:translateX(0) rotate(0)}}
    @keyframes qmSnitchWinner{from{opacity:0;transform:translate(-50%,-8px) scale(.95)}to{opacity:1;transform:translate(-50%,0) scale(1)}}
    #quidditchModePitch .qm-pet.is-snitch-dancing{z-index:92!important;animation:qmSnitchWinnerDance .34s ease-in-out infinite alternate!important}
    #quidditchModePitch .qm-caught-snitch{position:absolute;left:54%;top:-8px;width:22px;height:14px;object-fit:contain;image-rendering:pixelated;filter:drop-shadow(0 0 5px #ffe169);pointer-events:none;animation:qmCaughtSnitchBob .24s ease-in-out infinite alternate}
    @keyframes qmSnitchWinnerDance{from{transform:translateY(0) rotate(-4deg) scale(1.02)}to{transform:translateY(-7px) rotate(5deg) scale(1.08)}}
    @keyframes qmCaughtSnitchBob{from{transform:translate(-3px,2px) rotate(-12deg)}to{transform:translate(4px,-5px) rotate(12deg)}}
    @media(max-width:760px){
      #quidditchModePitch .qm-snitch-alert{width:min(310px,60%)}
      #quidditchModePitch .qm-snitch-caption{font-size:12px;min-width:195px;padding:6px 10px}
      #quidditchModePitch .qm-golden-snitch{width:32px;height:19px}
      #quidditchModePitch .qm-snitch-winner{min-width:210px;padding:8px 10px 9px}
      #quidditchModePitch .qm-snitch-winner b{font-size:16px}
    }
  `;
  document.head.appendChild(style);

  const playSnitchAppearSound=()=>{
    try{
      const audio=new Audio('assets/quidditch-snitch-appear.mp3');
      audio.preload='auto';audio.volume=.82;audio.currentTime=0;
      audio.play().catch(()=>{});
      later(()=>{try{audio.pause();audio.src='';}catch(_){}},6200);
    }catch(_){}
  };

  let snitchEventAudio=null;
  const stopSnitchEventAudio=()=>{
    if(!snitchEventAudio)return;
    try{snitchEventAudio.pause();snitchEventAudio.currentTime=0;snitchEventAudio.src='';}catch(_){}
    snitchEventAudio=null;
  };
  const startSnitchEventAudio=()=>{
    stopSnitchEventAudio();
    try{
      const audio=new Audio('assets/quidditch-snitch-event-voice.mp3');
      audio.preload='auto';audio.volume=.13;audio.currentTime=0;
      snitchEventAudio=audio;
      audio.play().catch(()=>{});
    }catch(_){}
  };

  const removeSnitchNodes=()=>{
    stopSnitchEventAudio();
    snitch.alert?.remove();snitch.alert=null;
    snitch.caption?.remove();snitch.caption=null;
    snitch.sprite?.remove();snitch.sprite=null;
    snitch.winnerBanner?.remove();snitch.winnerBanner=null;
    const pitch=getPitch();
    pitch?.classList.remove('is-snitch-event');
    pitch?.querySelectorAll('.qm-snitch-alert,.qm-snitch-caption,.qm-golden-snitch,.qm-snitch-winner').forEach(node=>node.remove());
    qmState?.pets?.forEach(p=>{
      p.classList.remove('is-snitch-catcher','is-snitch-bumped','is-snitch-dancing','is-celebrating');
      p.querySelectorAll('.qm-snitch-catcher-label,.qm-caught-snitch').forEach(node=>node.remove());
    });
  };

  const stopCurrentBroadcast=()=>{
    if(typeof qmSync!=='undefined'&&qmSync.raf){cancelAnimationFrame(qmSync.raf);qmSync.raf=null;}
    clearInterval(qmState.tick);qmState.tick=null;qmState.busy=true;qmState.carrier=null;
    const pitch=getPitch();
    pitch?.querySelectorAll('.qm-quaffle').forEach(node=>node.remove());
    (qmState.pets||[]).forEach(p=>p.classList.remove('has-ball'));
  };

  const setCaption=(text,result=false)=>{
    const pitch=getPitch();if(!pitch)return;
    snitch.caption?.remove();
    const caption=document.createElement('div');
    caption.className=`qm-snitch-caption${result?' is-result':''}`;
    caption.textContent=text;
    pitch.appendChild(caption);snitch.caption=caption;
  };

  const showAlert=()=>{
    const pitch=getPitch();if(!pitch)return;
    const alert=document.createElement('div');alert.className='qm-snitch-alert';
    alert.innerHTML='<img src="assets/quidditch-snitch-popup.png" alt="Golden Snitch has appeared">';
    pitch.appendChild(alert);snitch.alert=alert;
  };

  const createSnitchSprite=()=>{
    const pitch=getPitch();if(!pitch)return null;
    snitch.sprite?.remove();
    const el=document.createElement('div');
    el.className='qm-golden-snitch';
    el.innerHTML='<img src="assets/quidditch-golden-snitch.png" alt="Golden Snitch">';
    el.dataset.x='50';el.dataset.y='50';
    pitch.appendChild(el);snitch.sprite=el;
    return el;
  };

  const setSnitchPosition=(x,y)=>{
    const el=snitch.sprite||createSnitchSprite();if(!el)return;
    const nx=Math.max(8,Math.min(92,Number(x)||50));
    const ny=Math.max(14,Math.min(86,Number(y)||50));
    el.dataset.x=String(nx);el.dataset.y=String(ny);
    el.style.transition='none';el.style.left=`${nx}%`;el.style.top=`${ny}%`;
  };

  const seededChasePoints=matchId=>{
    const count=8+(qmHashNumber(`${matchId}:snitch-path-count`)%4); // 8–11 genuinely different turns
    const edge=qmHashNumber(`${matchId}:snitch-entry-edge`)%4;
    const edgePos=.18+qmUnit(`${matchId}:snitch-entry-pos`)*.64;
    const first=edge===0?{x:8,y:18+edgePos*64}:edge===1?{x:92,y:18+edgePos*64}:edge===2?{x:12+edgePos*76,y:15}:{x:12+edgePos*76,y:85};
    const points=[first];
    let previous=first;
    for(let i=1;i<count;i++){
      let chosen=null;
      for(let attempt=0;attempt<9;attempt++){
        const x=11+qmUnit(`${matchId}:snitch-path-x:${i}:${attempt}`)*78;
        const y=17+qmUnit(`${matchId}:snitch-path-y:${i}:${attempt}`)*66;
        const distance=Math.hypot(x-previous.x,y-previous.y);
        if(distance>=23||attempt===8){chosen={x,y};break;}
      }
      points.push({x:Number(chosen.x.toFixed(3)),y:Number(chosen.y.toFixed(3))});
      previous=chosen;
    }
    return points;
  };

  const catmull=(a,b,c,d,t)=>{
    const t2=t*t,t3=t2*t;
    return .5*((2*b)+(-a+c)*t+(2*a-5*b+4*c-d)*t2+(-a+3*b-3*c+d)*t3);
  };
  const sampleChasePath=(points,progress)=>{
    if(!points?.length)return{x:50,y:50};
    if(points.length===1)return points[0];
    const scaled=Math.max(0,Math.min(.999999,progress))*(points.length-1);
    const index=Math.floor(scaled),t=scaled-index;
    const p0=points[Math.max(0,index-1)],p1=points[index],p2=points[Math.min(points.length-1,index+1)],p3=points[Math.min(points.length-1,index+2)];
    return{x:Math.max(8,Math.min(92,catmull(p0.x,p1.x,p2.x,p3.x,t))),y:Math.max(14,Math.min(86,catmull(p0.y,p1.y,p2.y,p3.y,t)))};
  };
  const smoothStep=value=>{const t=Math.max(0,Math.min(1,value));return t*t*(3-2*t);};

  const bumpPair=(pets,mark,seed=snitch.matchId)=>{
    if(pets.length<2)return;
    const first=qmHashNumber(`${seed}:bump-a:${mark}`)%pets.length;
    let second=qmHashNumber(`${seed}:bump-b:${mark}`)%pets.length;
    if(second===first)second=(second+1)%pets.length;
    [pets[first],pets[second]].forEach((pet,index)=>{
      if(!pet)return;
      pet.style.setProperty('--snitch-bump-x',index===0?'8px':'-8px');
      pet.style.setProperty('--snitch-bump-r',index===0?'13deg':'-13deg');
      pet.classList.remove('is-snitch-bumped');void pet.offsetWidth;pet.classList.add('is-snitch-bumped');
      later(()=>pet.classList.remove('is-snitch-bumped'),460);
    });
  };

  const startSmoothChase=(matchId,durationMs,onComplete)=>{
    stopChaseAnimation();
    const pets=(qmState.pets||[]).filter(p=>p?.isConnected);
    const points=seededChasePoints(matchId);
    const starts=pets.map(p=>({x:Number(p.dataset.qx||50),y:Number(p.dataset.qy||50)}));
    const marks=new Set();
    snitch.chasePath=points;snitch.chaseStartedAt=performance.now();snitch.chaseDuration=durationMs;
    const first=points[0]||{x:50,y:50};setSnitchPosition(first.x,first.y);

    const frame=now=>{
      if(!snitch.active){snitch.raf=null;return;}
      const progress=Math.max(0,Math.min(1,(now-snitch.chaseStartedAt)/Math.max(1,durationMs)));
      const snitchPoint=sampleChasePath(points,progress);
      setSnitchPosition(snitchPoint.x,snitchPoint.y);

      pets.forEach((pet,index)=>{
        const lag=.045+qmUnit(`${matchId}:snitch-lag:${index}`)*.105;
        const followProgress=Math.max(0,Math.min(1,(progress-lag)/(1-lag)));
        const pathPoint=sampleChasePath(points,followProgress);
        const angle=(index/Math.max(1,pets.length))*Math.PI*2+Math.sin(progress*Math.PI*5+index*1.7)*.34;
        const radius=3.2+(index%4)*1.05+qmUnit(`${matchId}:snitch-radius:${index}`)*1.8;
        let tx=pathPoint.x+Math.cos(angle)*radius;
        let ty=pathPoint.y+Math.sin(angle)*radius*.72;
        if(progress<.16){
          const blend=smoothStep(progress/.16);
          tx=starts[index].x+(tx-starts[index].x)*blend;
          ty=starts[index].y+(ty-starts[index].y)*blend;
        }
        tx=Math.max(6,Math.min(94,tx));ty=Math.max(15,Math.min(85,ty));
        const oldX=Number(pet.dataset.qx||tx);
        pet.dataset.qx=String(tx);pet.dataset.qy=String(ty);
        pet.style.transition='none';pet.style.left=`${tx}%`;pet.style.top=`${ty}%`;
        pet.classList.toggle('is-leftward',tx<oldX-.025);
      });

      if(progress>=.30&&!marks.has('bump1')){marks.add('bump1');bumpPair(pets,'one',matchId);setCaption('PLAYERS COLLIDE IN THE CHASE!');}
      if(progress>=.58&&!marks.has('call')){marks.add('call');setCaption('THE WHOLE PITCH CHASES THE SNITCH…');}
      if(progress>=.76&&!marks.has('bump2')){marks.add('bump2');bumpPair(pets,'two',matchId);}

      if(progress<1)snitch.raf=requestAnimationFrame(frame);
      else{snitch.raf=null;onComplete?.();}
    };
    snitch.raf=requestAnimationFrame(frame);
  };

  const distanceToSnitch=pet=>{
    const sx=Number(snitch.sprite?.dataset.x||50),sy=Number(snitch.sprite?.dataset.y||50);
    const px=Number(pet?.dataset.qx||50),py=Number(pet?.dataset.qy||50);
    return Math.hypot(sx-px,sy-py);
  };

  const chooseCatcher=matchId=>{
    const pets=(qmState.pets||[]).filter(p=>p?.isConnected);
    if(!pets.length)return null;
    return pets.slice().sort((a,b)=>distanceToSnitch(a)-distanceToSnitch(b)||
      (qmHashNumber(`${matchId}:catcher:${a.dataset.name}`)-qmHashNumber(`${matchId}:catcher:${b.dataset.name}`)))[0]||pets[0];
  };

  const showWinnerBanner=(teamName,petName)=>{
    const pitch=getPitch();if(!pitch)return;
    snitch.winnerBanner?.remove();
    const banner=document.createElement('div');banner.className='qm-snitch-winner';
    banner.innerHTML=`<strong>GOLDEN SNITCH CAUGHT BY ${escapeHtml(String(petName||'Pet').toUpperCase())}!</strong><b>${escapeHtml(String(teamName||'TEAM').toUpperCase())} WIN</b><small>THE MATCH ENDS IMMEDIATELY</small>`;
    pitch.appendChild(banner);snitch.winnerBanner=banner;
  };

  const ensureWinningScores=(state,winnerSide,canonical=null)=>{
    const next={...(state||{})};
    const source=canonical||{};
    let left=Number(source.left_score??next.left_score)||0;
    let right=Number(source.right_score??next.right_score)||0;
    if(winnerSide==='left'&&left<=right)left=right+1;
    if(winnerSide==='right'&&right<=left)right=left+1;
    next.left_score=left;next.right_score=right;
    next.left_scorers=source.left_scorers||next.left_scorers||{};
    next.right_scorers=source.right_scorers||next.right_scorers||{};
    next.snitch_winner_side=winnerSide;
    next.snitch_winner_pet=snitch.winnerPet;
    return next;
  };

  // End a Snitch match through one idempotent path. This deliberately renders the
  // normal full-time presentation and then watches it for a few seconds so a late
  // live-state poll, suspended tab or overlapping animation cannot put the pitch
  // back into a half-finished state.
  const finishSnitchMatch=(state,winnerSide,canonical=null)=>{
    const source=snitch.latestState||state;
    if(!source||!winnerSide||!qmState?.open)return false;
    const sourceId=getMatchId(source);
    if(String(snitch.matchId||'')!==String(sourceId))return false;

    snitch.lockedFinal=true;
    snitch.active=false;
    snitch.test=false;
    snitch.finishCommitted=true;
    if(!snitch.finishedAt)snitch.finishedAt=Date.now();
    snitch.finalState=ensureWinningScores(source,winnerSide,canonical);
    snitch.finalState.phase='post';
    snitch.finalState.ended_by_snitch=true;
    snitch.finalState.phase_seconds=snitchPostSeconds();

    window.qmStopBarrySnitchFlybys?.();
    window.qmCancelBarrySetPiece?.();
    removeSnitchNodes();
    stopCurrentBroadcast();

    const render=()=>{
      if(!qmState?.open||!snitch.lockedFinal)return;
      if(String(qmState.liveState?.match_id||sourceId)!==String(sourceId))return;
      const finalState={...snitch.finalState,phase:'post',ended_by_snitch:true,phase_seconds:snitchPostSeconds()};
      qmApplyLiveState(finalState);
    };

    render();
    requestAnimationFrame(render);
    setTimeout(render,120);
    setTimeout(render,520);
    // Browsers can throttle normal intervals in a background tab. This independent
    // handoff runs just after the full 30-second presentation and is safe to repeat.
    setTimeout(()=>{
      if(snitch.lockedFinal&&String(snitch.matchId)===String(sourceId))forceSnitchNextMatch(sourceId);
    },SNITCH_POST_SECONDS*1000+350);

    clearFinishWatchdog();
    const started=Date.now();
    snitch.finishWatchdog=setInterval(()=>{
      if(!qmState?.open||!snitch.lockedFinal||String(snitch.matchId)!==String(sourceId)||Date.now()-started>7000){
        clearFinishWatchdog();return;
      }
      // Re-render throughout the standard 30-second post-match window so the
      // visible countdown ticks down even while the authoritative match row is
      // still reporting the abandoned live-match time.
      render();
    },350);
    return true;
  };

  // The Snitch result is committed through one atomic server RPC. The first
  // viewer guarantees the catching side leads and moves the shared match directly
  // into a fresh 30-second POST phase; every other viewer receives the same result.
  const awardSnitchCatcherOwner=async(state,catcher)=>{
    if(!state?.match_id||!catcher||typeof db==='undefined')return null;
    const ownerUsername=String(catcher.dataset.ownerUsername||'').trim();
    if(!ownerUsername)return null;
    try{
      const {data,error}=await db.rpc('award_quidditch_snitch_catch',{ 
        p_match_id:String(state.match_id),
        p_pet_name:String(catcher.dataset.name||'Pet').slice(0,80),
        p_owner_username:ownerUsername.slice(0,80)
      });
      if(error){console.warn('Golden Snitch GP reward:',error);return null;}
      const row=Array.isArray(data)?data[0]:data;
      if(row?.awarded&&character&&String(character.username||'').toLowerCase()===ownerUsername.toLowerCase()){
        character.gp=Number(row.new_gp)||Number(character.gp)||0;
        renderCharacter?.();
        toast(`Golden Snitch reward: +5,000 GP for ${catcher.dataset.name||'your pet'}!`,5000);
      }
      return row||null;
    }catch(error){console.warn('Golden Snitch GP reward:',error);return null;}
  };

  const commitSnitchWin=async(state,catcher,winnerSide)=>{
    if(!state?.match_id||!catcher||typeof db==='undefined')return null;
    const petName=String(catcher.dataset.name||'Pet').slice(0,80);
    try{
      // Prefer the v2 bigint RPC: it is unambiguous in PostgREST and also repairs
      // a match that was locally finished before the server received the catch.
      let response=await db.rpc('finish_live_quidditch_by_snitch_v2',{
        p_match_id:Number(state.match_id),
        p_winner_side:winnerSide,
        p_winner_pet:petName
      });
      // Compatibility with sites that have not yet run the v2 migration.
      if(response.error){
        response=await db.rpc('finish_live_quidditch_by_snitch',{
          p_match_id:String(state.match_id),
          p_winner_side:winnerSide,
          p_winner_pet:petName
        });
      }
      const {data,error}=response;
      if(!error){
        const canonical=Array.isArray(data)?data[0]:data;
        if(canonical){
          qmApplyCanonicalScore(canonical);
          // Anchor the local display to the server's exact remaining POST time.
          const remaining=Math.max(0,Math.min(30,Number(canonical.phase_seconds)||30));
          snitch.finishedAt=Date.now()-((30-remaining)*1000);
          return canonical;
        }
      }else{
        console.warn('Golden Snitch authoritative finish:',error);
      }
    }catch(error){console.warn('Golden Snitch authoritative finish:',error);}

    // Compatibility fallback for a database that has not yet had the supplied
    // migration applied. This preserves the winning score, but the SQL migration
    // is required for the shared match itself to restart after exactly 30 seconds.
    const snapshot=snitch.latestState||state;
    const left=Number(snapshot.left_score)||0,right=Number(snapshot.right_score)||0;
    const required=winnerSide==='left'?Math.max(1,right-left+1):Math.max(1,left-right+1);
    const goalCount=Math.min(30,required);
    let canonical=null;
    for(let i=0;i<goalCount;i++){
      try{
        const {data,error}=await db.rpc('record_live_quidditch_goal',{
          p_match_id:state.match_id,
          p_side:winnerSide,
          p_pet_name:petName,
          p_event_key:`snitch:${state.match_id}:${winnerSide}:${i}`
        });
        if(error){console.warn('Golden Snitch score fallback:',error);break;}
        canonical=data?.[0]||canonical;
      }catch(error){console.warn('Golden Snitch score fallback:',error);break;}
    }
    if(canonical)qmApplyCanonicalScore(canonical);
    return canonical;
  };

  // At zero the browser asks the database to complete the handoff itself.
  // This is deliberately idempotent and rate-limited: every viewer may call it,
  // but only the shared clock row can advance once. It prevents a failed/late
  // heartbeat from leaving the FULL TIME screen parked at 0 seconds.
  const forceSnitchNextMatch=async matchId=>{
    const numericId=Number(matchId);
    if(!Number.isSafeInteger(numericId)||numericId<=0||typeof db==='undefined'||!db?.rpc)return false;
    const now=Date.now();
    if(snitch.handoffRunning||now-snitch.handoffLastAt<900)return false;
    snitch.handoffRunning=true;snitch.handoffLastAt=now;
    try{
      const {error}=await db.rpc('force_advance_quidditch_after_snitch',{
        p_match_id:numericId,
        p_winner_side:String(snitch.winnerSide||''),
        p_winner_pet:String(snitch.winnerPet||'Pet')
      });
      if(error){
        console.warn('Golden Snitch next-match handoff:',error);
        // Keep the ordinary poll alive as a compatibility fallback.
        try{await qmPollLiveState(true);}catch(_){}
        return false;
      }
      try{await qmPollLiveState(true);}catch(_){}
      return true;
    }catch(error){
      console.warn('Golden Snitch next-match handoff:',error);
      return false;
    }finally{snitch.handoffRunning=false;}
  };

  const applyLockedPresentation=state=>{
    if(!state||!qmState?.open)return;
    stopCurrentBroadcast();
    qmState.leftName=String(state.left_name||qmState.leftName||'LEFT');
    qmState.rightName=String(state.right_name||qmState.rightName||'RIGHT');
    qmApplyCanonicalScore({
      left_score:state.left_score,right_score:state.right_score,
      left_scorers:state.left_scorers||{},right_scorers:state.right_scorers||{}
    });
    if($('qmStatus'))$('qmStatus').textContent='GOLDEN SNITCH';
    if($('qmTimer'))$('qmTimer').textContent='FINAL';
  };

  const restoreBroadcast=()=>{
    window.qmStopBarrySnitchFlybys?.();
    window.qmCancelBarrySetPiece?.();
    removeSnitchNodes();snitch.active=false;snitch.test=false;
    if(snitch.lockedFinal||!qmState?.open||qmState.liveState?.phase!=='live')return;
    qmState.busy=false;
    try{qmStartSyncedBroadcast(qmState.liveState);}catch(error){console.warn('Snitch broadcast resume:',error);}
  };

  async function runSnitchEvent({test=false,state=qmState.liveState}={}){
    if(snitch.active||snitch.lockedFinal||!qmState?.open||state?.phase!=='live'||!qmState.pets?.length)return false;
    if(window.repoQuidditchPenaltyState?.active)return false;
    snitch.active=true;snitch.test=!!test;snitch.latestState=state;
    clearTimers();removeSnitchNodes();stopCurrentBroadcast();
    const pitch=getPitch();if(!pitch){snitch.active=false;return false;}
    pitch.classList.add('is-snitch-event');
    snitch.matchId=getMatchId(state);
    const eventSeed=test?`${snitch.matchId}:admin-preview:${Date.now()}`:snitch.matchId;
    playSnitchAppearSound();startSnitchEventAudio();showAlert();setCaption('GOLDEN SNITCH HAS APPEARED!');
    window.qmStartBarrySetPiece?.('snitch');
    qmAddCommentary?.('snitchAppeared',{},true);

    const chaseMs=5000+((qmHashNumber(`${eventSeed}:snitch-duration`)%6)*1000); // 5–10 seconds
    window.qmStartBarrySnitchFlybys?.(chaseMs);

    const finishCatch=async()=>{
      if(!snitch.active)return;
      stopSnitchEventAudio();
      const catcher=chooseCatcher(eventSeed)||qmState.pets[0];
      const sx=Number(snitch.sprite?.dataset.x||50),sy=Number(snitch.sprite?.dataset.y||50);
      if(catcher){
        catcher.classList.add('is-snitch-catcher','is-celebrating');
        catcher.style.transition='left .34s ease-out,top .34s ease-out,transform .25s ease';
        catcher.dataset.qx=String(sx);catcher.dataset.qy=String(sy);
        catcher.style.left=`${sx}%`;catcher.style.top=`${sy}%`;
        catcher.querySelector('.qm-snitch-catcher-label')?.remove();
        const catcherLabel=document.createElement('div');
        catcherLabel.className='qm-snitch-catcher-label';
        catcherLabel.textContent=`${catcher.dataset.name||'PET'} CAUGHT IT!`;
        catcher.appendChild(catcherLabel);
        later(()=>catcherLabel.remove(),2800);
        catcher.classList.add('is-snitch-dancing');
        const caughtSnitch=document.createElement('img');
        caughtSnitch.className='qm-caught-snitch';
        caughtSnitch.src='assets/quidditch-golden-snitch.png';
        caughtSnitch.alt='Caught Golden Snitch';
        catcher.appendChild(caughtSnitch);
        later(()=>{catcher.classList.remove('is-celebrating','is-snitch-dancing');caughtSnitch.remove();},2700);
      }
      const petName=catcher?.dataset.name||'Pet';
      const winnerSide=catcher?.dataset.team||'left';
      const teamName=winnerSide==='left'?qmState.leftName:qmState.rightName;
      snitch.winnerPet=petName;snitch.winnerSide=winnerSide;
      snitch.caughtAt=Date.now();snitch.finishedAt=0;snitch.finishCommitted=false;
      setCaption(`GOLDEN SNITCH CAUGHT BY ${petName}!`,true);
      showWinnerBanner(teamName,petName);
      qmAddCommentary?.('snitchCaught',{pet:petName,team:teamName},true);
      window.qmStopBarrySnitchFlybys?.();
      window.qmResolveBarrySetPiece?.(true,`${petName} catches the Golden Snitch!`);
      qmPlayGoalSound?.();qmFireworks?.(sx,sy);
      later(()=>{snitch.sprite?.remove();snitch.sprite=null;},480);

      if(test){
        later(()=>catcher?.classList.remove('is-snitch-catcher'),2750);
        later(restoreBroadcast,3200);
        return;
      }

      // Award the catching pet's account owner once per match.
      awardSnitchCatcherOwner(state,catcher).catch(()=>{});

      // Hold on the winning pet for a short dance, then always enter the normal
      // full-time screen. The untracked backup timeout is intentional: it cannot be
      // lost if another animation clears the event timer set during the celebration.
      const completeCatch=()=>{
        if(snitch.finishCommitted||snitch.test||String(snitch.matchId)!==String(getMatchId(state)))return;
        const latest=snitch.latestState||state;
        finishSnitchMatch(latest,winnerSide);
        commitSnitchWin(latest,catcher,winnerSide).then(canonical=>{
          if(!snitch.lockedFinal||String(snitch.finalState?.match_id||'')!==String(state.match_id||''))return;
          snitch.finalState=ensureWinningScores(snitch.finalState,winnerSide,canonical);
          snitch.finalState.phase='post';snitch.finalState.ended_by_snitch=true;
          finishSnitchMatch(snitch.finalState,winnerSide,canonical);
        }).catch(()=>{});
      };
      later(completeCatch,2600);
      setTimeout(()=>{
        if(!qmState?.open||snitch.test||snitch.finishCommitted)return;
        if(String(snitch.matchId)!==String(getMatchId(state)))return;
        completeCatch();
      },3050);
    };

    later(()=>{
      if(!snitch.active)return;
      snitch.alert?.remove();snitch.alert=null;
      createSnitchSprite();
      setCaption('ALL PLAYERS ABANDON THE QUAFFLE!');
      startSmoothChase(eventSeed,chaseMs,finishCatch);
    },1280);
    return true;
  }
  window.qmTestSnitchEvent=()=>runSnitchEvent({test:true,state:qmState.liveState});

  // Keep all normal Quaffle actions paused during the chase and after the catch.
  if(typeof qmStartSyncedBroadcast==='function'){
    const baseStart=qmStartSyncedBroadcast;
    qmStartSyncedBroadcast=function(state){if(snitch.active||snitch.lockedFinal)return;return baseStart(state);};
  }
  if(typeof qmShowSharedGoal==='function'){
    const baseGoal=qmShowSharedGoal;
    qmShowSharedGoal=function(state){if(snitch.active||snitch.lockedFinal)return;return baseGoal(state);};
  }

  if(typeof qmApplyLiveState==='function'){
    const baseApply=qmApplyLiveState;
    qmApplyLiveState=function(state){
      if(!state)return baseApply(state);
      const incomingId=String(state.match_id||'');
      const currentId=String(snitch.matchId||'');

      // A new authoritative match releases the locally finished Snitch match.
      if(currentId&&incomingId&&incomingId!==currentId){
        clearTimers();window.qmStopBarrySnitchFlybys?.();window.qmCancelBarrySetPiece?.();removeSnitchNodes();
        clearFinishWatchdog();
        snitch.active=false;snitch.test=false;snitch.lockedFinal=false;snitch.finishCommitted=false;snitch.caughtAt=0;snitch.finishedAt=0;
        snitch.handoffRunning=false;snitch.handoffLastAt=0;
        snitch.finalState=null;snitch.latestState=null;snitch.winnerSide='';snitch.winnerPet='';
        snitch.matchId=incomingId;snitch.autoTriggered=false;qmState.busy=false;
        return baseApply(state);
      }

      snitch.latestState=state;
      if(snitch.active){
        if(typeof qmSync!=='undefined'&&qmSync.raf){cancelAnimationFrame(qmSync.raf);qmSync.raf=null;}
        if(!snitch.test&&snitch.winnerSide&&snitch.caughtAt&&Date.now()-snitch.caughtAt>=2550){
          finishSnitchMatch(state,snitch.winnerSide);
        }
        return;
      }

      if(snitch.lockedFinal){
        // A caught Snitch ends the viewed match immediately. While the authoritative
        // server row is still technically live, keep presenting a synthetic post
        // state so later polling cannot put viewers back onto the frozen pitch.
        const source=state.phase==='post'?state:(snitch.finalState||state);
        const finalState=ensureWinningScores(source,snitch.winnerSide);
        finalState.phase='post';
        finalState.phase_seconds=snitchPostSeconds();
        snitch.finalState=finalState;
        removeSnitchNodes();
        const applied=baseApply(finalState);
        if(finalState.phase_seconds<=0)forceSnitchNextMatch(snitch.matchId);
        return applied;
      }

      const result=baseApply(state);
      if(!qmState.open)return result;
      const matchId=getMatchId(state);
      if(matchId!==snitch.matchId){snitch.matchId=matchId;snitch.autoTriggered=false;}
      if(state.phase!=='live'||snitch.autoTriggered||window.repoQuidditchPenaltyState?.active)return result;

      // Exact 1-in-14 schedule. The shared scheduler uses disjoint slots,
      // so a Golden Snitch can never be displaced by a penalty match.
      const eligible=qmNaturalQuidditchSetPiece(matchId)==='snitch';
      if(!eligible)return result;
      const elapsed=Math.max(0,180-Number(state.phase_seconds||180));
      const triggerAt=30+(qmHashNumber(`${matchId}:snitch-time`)%94); // 0:30–2:03
      // No narrow timing window: viewers joining after the trigger still receive
      // the same shared event rather than seeing the supposedly finished match.
      if(elapsed>=triggerAt){
        snitch.autoTriggered=true;runSnitchEvent({test:false,state});
      }
      return result;
    };
  }

  const ensureAdminButton=()=>{
    const panel=document.getElementById('qmAdminSpecialTester');
    if(!panel||document.getElementById('qmTestSnitchEvent'))return;
    const button=document.createElement('button');
    button.type='button';button.id='qmTestSnitchEvent';button.textContent='TEST SNITCH';
    button.title='Preview the Golden Snitch chase without changing the score or ending the match';
    button.addEventListener('click',()=>{
      const isCat=String(character?.username||'').toLowerCase()==='catasthma';
      if(!isCat||!toaState?.adminMode)return;
      if(!qmState.open||qmState.liveState?.phase!=='live'){
        toast('Open Quidditch Mode during a live match to test the Golden Snitch.',3600);return;
      }
      runSnitchEvent({test:true,state:qmState.liveState});
    });
    const penaltyButton=panel.querySelector('#qmTestPenaltyEvent');
    if(penaltyButton?.parentElement)penaltyButton.parentElement.appendChild(button);
    else panel.appendChild(button);
  };
  ensureAdminButton();setTimeout(ensureAdminButton,120);setTimeout(ensureAdminButton,650);
  new MutationObserver(ensureAdminButton).observe(document.documentElement,{childList:true,subtree:true});

  const abortSnitch=()=>{
    clearTimers();window.qmStopBarrySnitchFlybys?.();window.qmCancelBarrySetPiece?.();removeSnitchNodes();
    const wasLocked=snitch.lockedFinal;
    clearFinishWatchdog();
    snitch.active=false;snitch.test=false;snitch.lockedFinal=false;snitch.finishCommitted=false;snitch.caughtAt=0;snitch.finishedAt=0;
    snitch.handoffRunning=false;snitch.handoffLastAt=0;
    snitch.finalState=null;snitch.latestState=null;snitch.winnerSide='';snitch.winnerPet='';qmState.busy=false;
    if(!wasLocked&&qmState?.open&&qmState.liveState?.phase==='live'){
      try{qmStartSyncedBroadcast(qmState.liveState);}catch(_){}
    }
  };
  window.qmAbortSnitchEvent=abortSnitch;
  const baseClose=closeQuidditchMode;
  closeQuidditchMode=function(){abortSnitch();return baseClose();};
  document.getElementById('quidditchModeClose')?.addEventListener('click',abortSnitch,true);
  document.getElementById('quidditchModeOverlay')?.addEventListener('click',event=>{if(event.target===event.currentTarget)abortSnitch();},true);
  document.addEventListener('keydown',event=>{if(event.key==='Escape'&&(snitch.active||snitch.lockedFinal))abortSnitch();},true);
})();


// --- Quidditch special-event full-time details ---
(function installQuidditchSpecialEventFullTimeDetails(){
  if(window.__qmSpecialEventFullTimeDetailsInstalled)return;
  window.__qmSpecialEventFullTimeDetailsInstalled=true;

  const style=document.createElement('style');
  style.id='qmSpecialEventFullTimeStyles';
  style.textContent=`
    #quidditchModePitch .qm-special-finish-note{margin:8px 14px 2px;padding:8px 12px;border:2px solid #d7a940;background:linear-gradient(180deg,#54130f,#270706);color:#ffe49a;text-align:center;font:900 13px/1.2 Georgia,serif;letter-spacing:.45px;text-transform:uppercase;box-shadow:0 3px 0 #110303,0 0 12px rgba(255,201,64,.2)}
    #quidditchModePitch .qm-special-finish-note strong{color:#fff5c9}
  `;
  document.head.appendChild(style);

  const baseRender=qmRenderFullTimeStats;
  qmRenderFullTimeStats=function(state){
    baseRender(state);
    const card=document.querySelector('#quidditchModePitch .qm-full-time-stats');
    if(!card||!state)return;

    // Mark the penalty scorer in the normal goalscorer list.
    const penalties=window.__qmPenaltyGoals?.[String(state.match_id||'')]||{};
    if(Object.keys(penalties).length){
      card.querySelectorAll('.qm-match-scorers p').forEach(row=>{
        const name=row.querySelector('b');
        if(name&&Number(penalties[name.textContent.trim()])>0&&!/\(P\)$/.test(name.textContent))name.textContent=`${name.textContent} (P)`;
      });
    }

    // Explain clearly when the Snitch ended the match.
    const pet=String(state.snitch_winner_pet||window.repoQuidditchSnitchState?.winnerPet||'').trim();
    const side=String(state.snitch_winner_side||window.repoQuidditchSnitchState?.winnerSide||'').trim();
    if(pet&&side){
      const team=side==='left'?state.left_name:state.right_name;
      const note=document.createElement('div');
      note.className='qm-special-finish-note';
      note.innerHTML=`GOLDEN SNITCH CAUGHT BY <strong>${escapeHtml(pet)}</strong> · <strong>${escapeHtml(team||'THEIR TEAM')}</strong> WIN THE MATCH`;
      const header=card.querySelector('header');
      header?.insertAdjacentElement('afterend',note);
    }
  };
})();

// --- Quidditch Hat Trick broadcast popup ---
(function(){
  if(window.__qmHatTrickInstalled)return;
  window.__qmHatTrickInstalled=true;
  const shownGoalIds=new Set();

  function playHatTrickChime(){
    try{
      const AudioCtx=window.AudioContext||window.webkitAudioContext;
      if(!AudioCtx)return;
      const ctx=new AudioCtx();
      const master=ctx.createGain();
      master.gain.setValueAtTime(0.0001,ctx.currentTime);
      master.gain.exponentialRampToValueAtTime(0.075,ctx.currentTime+0.018);
      master.gain.exponentialRampToValueAtTime(0.0001,ctx.currentTime+0.48);
      master.connect(ctx.destination);
      [659.25,783.99,987.77].forEach((freq,index)=>{
        const osc=ctx.createOscillator();
        const gain=ctx.createGain();
        osc.type='triangle';
        osc.frequency.value=freq;
        gain.gain.setValueAtTime(0.0001,ctx.currentTime+index*0.07);
        gain.gain.exponentialRampToValueAtTime(0.32,ctx.currentTime+index*0.07+0.012);
        gain.gain.exponentialRampToValueAtTime(0.0001,ctx.currentTime+index*0.07+0.22);
        osc.connect(gain);gain.connect(master);
        osc.start(ctx.currentTime+index*0.07);
        osc.stop(ctx.currentTime+index*0.07+0.24);
      });
      setTimeout(()=>ctx.close().catch(()=>{}),700);
    }catch(_){ }
  }

  function showHatTrickPopup(petName){
    const pitch=document.getElementById('quidditchModePitch');
    if(!pitch)return;
    pitch.querySelectorAll('.qm-hat-trick-popup').forEach(node=>node.remove());
    const wrap=document.createElement('div');
    wrap.className='qm-hat-trick-popup';
    wrap.setAttribute('aria-label',`${petName} has scored a hat trick`);
    const img=document.createElement('img');
    img.src='assets/quidditch-hat-trick-popup.png';
    img.alt='Hat Trick!';
    wrap.appendChild(img);
    pitch.appendChild(wrap);
    playHatTrickChime();
    requestAnimationFrame(()=>wrap.classList.add('is-visible'));
    setTimeout(()=>wrap.classList.add('is-leaving'),1450);
    setTimeout(()=>wrap.remove(),1850);
  }

  const style=document.createElement('style');
  style.textContent=`
    #quidditchModePitch .qm-hat-trick-popup{
      position:absolute;left:50%;top:48%;z-index:190;
      width:min(58%,430px);pointer-events:none;
      opacity:0;transform:translate(-50%,-50%) scale(.82);
      transform-origin:center;filter:drop-shadow(0 8px 12px rgba(0,0,0,.48));
    }
    #quidditchModePitch .qm-hat-trick-popup img{
      display:block;width:100%;height:auto;object-fit:contain;
    }
    #quidditchModePitch .qm-hat-trick-popup.is-visible{
      opacity:1;animation:qmHatTrickPop .42s cubic-bezier(.18,.8,.26,1.18) both,
        qmHatTrickShake .34s ease-in-out .42s 2;
    }
    #quidditchModePitch .qm-hat-trick-popup.is-leaving{
      animation:qmHatTrickOut .34s ease-in both;
    }
    @keyframes qmHatTrickPop{
      0%{opacity:0;transform:translate(-50%,-50%) scale(.7)}
      70%{opacity:1;transform:translate(-50%,-50%) scale(1.06)}
      100%{opacity:1;transform:translate(-50%,-50%) scale(1)}
    }
    @keyframes qmHatTrickShake{
      0%,100%{transform:translate(-50%,-50%) rotate(0deg)}
      25%{transform:translate(calc(-50% - 4px),-50%) rotate(-1deg)}
      75%{transform:translate(calc(-50% + 4px),-50%) rotate(1deg)}
    }
    @keyframes qmHatTrickOut{
      from{opacity:1;transform:translate(-50%,-50%) scale(1)}
      to{opacity:0;transform:translate(-50%,-55%) scale(.88)}
    }
  `;
  document.head.appendChild(style);

  if(typeof qmShowSharedGoal==='function'){
    const baseShowSharedGoal=qmShowSharedGoal;
    qmShowSharedGoal=function(state){
      const result=baseShowSharedGoal(state);
      try{
        const goalId=String(state?.latest_goal_id||'');
        const petName=String(state?.latest_goal_pet||'').trim();
        const side=state?.latest_goal_side;
        const scorers=side==='left'?(state?.left_scorers||{}):(state?.right_scorers||{});
        const count=Number(scorers?.[petName]||0);
        if(goalId&&petName&&count===3&&!shownGoalIds.has(goalId)){
          shownGoalIds.add(goalId);
          setTimeout(()=>showHatTrickPopup(petName),720);
        }
      }catch(error){console.warn('Hat trick popup:',error);}
      return result;
    };
  }

  // CatAsthma admin preview: plays only the popup/chime and never changes
  // the match score, scorer totals, rewards or live match state.
  window.qmTestHatTrickPopup=function(){
    const isCat=String(character?.username||'').toLowerCase()==='catasthma';
    if(!isCat||!toaState?.adminMode)return;
    if(!qmState?.open){toast('Open Quidditch Mode to test the Hat Trick popup.',3200);return;}
    const petName=String(qmState?.pets?.[0]?.dataset?.name||character?.active_pet_name||'Test Pet');
    showHatTrickPopup(petName);
    try{qmAddCommentary?.('goal',{pet:petName,team:'ADMIN TEST'},true);}catch(_){}
  };

  function ensureHatTrickAdminButton(){
    const panel=document.getElementById('qmAdminSpecialTester');
    if(!panel||document.getElementById('qmTestHatTrickEvent'))return;
    const button=document.createElement('button');
    button.type='button';
    button.id='qmTestHatTrickEvent';
    button.textContent='TEST HAT TRICK';
    button.title='Preview the Hat Trick popup without changing the score';
    button.addEventListener('click',window.qmTestHatTrickPopup);
    const snitchButton=panel.querySelector('#qmTestSnitchEvent');
    const penaltyButton=panel.querySelector('#qmTestPenaltyEvent');
    const anchor=snitchButton||penaltyButton||panel.querySelector('#qmTestAllSpecials');
    if(anchor?.parentElement)anchor.parentElement.appendChild(button);
    else panel.appendChild(button);
  }
  ensureHatTrickAdminButton();
  setTimeout(ensureHatTrickAdminButton,140);
  setTimeout(ensureHatTrickAdminButton,700);
  new MutationObserver(ensureHatTrickAdminButton).observe(document.documentElement,{childList:true,subtree:true});
})();

